def expect(val):
    # Inner class for method binding
    class Assertion:
        def __init__(self, value):
            self.value = value

        def _same(self, a, b):
            # Mimic JS "===": containers compare by identity, primitives by type and value
            if isinstance(a, (list, dict, set)) or isinstance(b, (list, dict, set)):
                return a is b
            return type(a) == type(b) and a == b

        def toBe(self, val2):
            if self._same(self.value, val2):
                return True
            raise Exception("Not Equal")

        def notToBe(self, val2):
            if self._same(self.value, val2):
                raise Exception("Equal")
            return True

    return Assertion(val)
